package com.ospfranco.trustmail.security

import android.content.Context

/**
 * Registrable-domain lookup (the "eTLD+1") backed by the Public Suffix List.
 * `assets/public_suffix_list.dat` is generated by `scripts/update-public-suffix-list.sh`.
 */
class PublicSuffixList(contents: String) {
    private val rules = HashSet<String>()
    private val wildcards = HashSet<String>()
    private val exceptions = HashSet<String>()

    /** One rule per line: `example.com`, `*.example.com` or `!www.example.com`. */
    init {
        for (line in contents.lineSequence()) {
            val rule = line.trim()
            when {
                rule.isEmpty() -> {}
                rule.startsWith("!") -> exceptions.add(rule.substring(1))
                rule.startsWith("*.") -> wildcards.add(rule.substring(2))
                else -> rules.add(rule)
            }
        }
    }

    /**
     * The registrable domain of [host] (e.g. `bbc.co.uk` for `www.bbc.co.uk`), or null when [host]
     * is itself a public suffix.
     */
    fun registrableDomain(host: String): String? {
        val labels = host.lowercase().split(".")
        val count = labels.size
        if (labels.any { it.isEmpty() }) return null

        var suffixLength = 1 // the implicit "*" rule: an unlisted TLD is its own suffix
        for (i in 0 until count) {
            if (labels.subList(i, count).joinToString(".") in exceptions) {
                // An exception rule is never a suffix itself; its parent is.
                return domain(labels, count - i - 1)
            }
            if (labels.subList(i, count).joinToString(".") in rules) suffixLength = maxOf(suffixLength, count - i)
            if (i + 1 < count && labels.subList(i + 1, count).joinToString(".") in wildcards) {
                suffixLength = maxOf(suffixLength, count - i)
            }
        }
        return domain(labels, suffixLength)
    }

    private fun domain(labels: List<String>, suffixLength: Int): String? {
        if (suffixLength >= labels.size) return null
        return labels.subList(labels.size - suffixLength - 1, labels.size).joinToString(".")
    }

    companion object {
        /** Set once at startup (see `TrustmailApplication`); tests assign their own. */
        lateinit var shared: PublicSuffixList

        fun load(context: Context): PublicSuffixList =
            PublicSuffixList(context.assets.open("public_suffix_list.dat").bufferedReader().use { it.readText() })
    }
}
